-- ============================================
-- 00031 Seven2 showcase: schema + seed
--
-- 1. Snapshot columns so historical builders/respondents don't need
--    real auth users (mirrors awards.winner_name). user_id is relaxed
--    to nullable; the new /[slug]/final route reads builder_name /
--    respondent_name and the public showcase uses the admin client.
-- 2. organizations.is_internal so Seven2 (our own event, seeded as the
--    case study) is excluded from Murtopolis owner metrics.
-- 3. Seeds the Seven2 Hacks-a-Thon as a real, revealed, public event:
--    19 projects (one per participant), 6 awards, 8 blocks, 7 reflection
--    questions, every reflection answer, and an approved AI recap.
--
-- Idempotent: re-running deletes the prior Seven2 org/event (cascades)
-- and re-inserts.
-- ============================================

-- --- 1. Schema ---------------------------------------------------------
ALTER TABLE ideas ADD COLUMN IF NOT EXISTS builder_name TEXT;
ALTER TABLE ideas ALTER COLUMN user_id DROP NOT NULL;
COMMENT ON COLUMN ideas.builder_name IS
  'Snapshot display name for the builder when there is no linked profile (historical/seeded showcase data). Public pages prefer the joined profile name, then this.';

ALTER TABLE reflections ADD COLUMN IF NOT EXISTS respondent_name TEXT;
ALTER TABLE reflections ALTER COLUMN user_id DROP NOT NULL;
COMMENT ON COLUMN reflections.respondent_name IS
  'Snapshot display name for the respondent when there is no linked profile (historical/seeded reflections).';

ALTER TABLE organizations ADD COLUMN IF NOT EXISTS is_internal BOOLEAN NOT NULL DEFAULT false;
COMMENT ON COLUMN organizations.is_internal IS
  'Murtopolis-owned org (e.g. the seeded Seven2 case study). Excluded from owner analytics in lib/murtopolis/queries.ts.';

-- --- 2. Idempotency: clear any prior Seven2 seed -----------------------
DELETE FROM events WHERE vanity_slug = 'seven2';
DELETE FROM organizations WHERE slug = 'seven2';

-- --- 3. Org + event ----------------------------------------------------
