INSERT INTO blocks (event_id, block_key, title, subtitle, duration_minutes, description, purpose, status, sort_order) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', 'ZERO', 'Kickoff', NULL, 15, 'Introduce Lovable, explain vibe coding, set expectations, and outline the structure.', 'Remove intimidation and create clarity before ideas begin.', 'completed', 0);
INSERT INTO blocks (event_id, block_key, title, subtitle, duration_minutes, description, purpose, status, sort_order) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', '01', 'Sprint to the IdeaLab', NULL, 30, 'Your chance to brainstorm, define and submit your project idea at IdeaLab.seven2.com', 'Commit to a direction and articulate why the idea matters to you.', 'completed', 1);
INSERT INTO blocks (event_id, block_key, title, subtitle, duration_minutes, description, purpose, status, sort_order) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', '02', 'Shark Tank, Minus the Sharks', NULL, 45, 'Each participant delivers a 1-minute pitch with light feedback from the team.', 'Sharpen ideas and build collective energy.', 'completed', 2);
INSERT INTO blocks (event_id, block_key, title, subtitle, duration_minutes, description, purpose, status, sort_order) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', '03', 'Documentation Is Everything', NULL, 30, 'Develop specifics around your idea using AI, ZERO.Prmptr.ai, IdeaLab, or all three.', 'Translate the idea into a low-prompt, buildable direction.', 'completed', 3);
INSERT INTO blocks (event_id, block_key, title, subtitle, duration_minutes, description, purpose, status, sort_order) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', '04', 'Here We Go!', 'Build Session 1', 45, 'It''s time to start your project in Lovable!', 'Jumpstart development of your idea.', 'completed', 4);
INSERT INTO blocks (event_id, block_key, title, subtitle, duration_minutes, description, purpose, status, sort_order) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', '05', 'Build Session 2', NULL, 45, 'Protected build time with optional office hours.', 'Iterate and improve.', 'completed', 5);
INSERT INTO blocks (event_id, block_key, title, subtitle, duration_minutes, description, purpose, status, sort_order) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', '06', 'Your Final Build Session', NULL, 45, 'This is your last time-blocked build session.', 'Polish demo flow and prepare for showcase.', 'completed', 6);
INSERT INTO blocks (event_id, block_key, title, subtitle, duration_minutes, description, purpose, status, sort_order) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', 'FINAL', 'Showcase Showdown', NULL, 120, 'Each participant presents a 3-minute demo followed by 2-minute Q&A.', 'Celebrate learning, reflect on insights, and capture takeaways.', 'completed', 7);
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('3c0cc2d2-0691-48f4-8749-e97c6dea5a05', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Nick Murto', 'HyperChrono', 'A time-lapse video stopwatch: Record something difficult. Speed it up to share on social. Prove you did it.', 'I finish every workout by holding a plank that lasts at least 3 minutes. I record it and post a time-lapse… but the problem is, you can’t actually tell how long I held it. There is no proof. 
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('e8e8ff15-05cc-4679-9a73-4c07bdbfd6b1', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Tyler Lafferty', 'Slingshot PTO Tracker', 'A simple, yet elegant way to track and approve PTO.', 'Slinghost PTO Tracker is a streamlined vacation, sick and personal time tracker designed for the modern workplace. Designed with a beautiful, Spotify-influenced user experience and utilizing your Google authentication, Slingshot PTO tracker eliminates the friction of requesting and approving leave. No more digging through emails or guessing balances. It’s all right there.', 'completed', 'https://slingshotptotracker.lovable.app', 'https://yjhgzukmrzufhevzstcw.supabase.co/storage/v1/object/public/idea-screenshots/e8e8ff15-05cc-4679-9a73-4c07bdbfd6b1/final.png', '2026-02-24T00:00:00Z', '2026-03-13T00:00:00Z');
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('556470e8-ff5c-490a-b949-000d6ca0a6d0', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Carlos Lantz', '"Cut-up" lyric idea generator', 'Make an app that will mimic the surrealist technique', 'User inputs sentences, phrases, paragraphs, descriptions or stories and the tool will cut them into four or five word sections and reassemble them in a random order to create ideas, accidental sense and unexpected imagery.', 'completed', 'https://syntaxscrambler.lovable.app', 'https://yjhgzukmrzufhevzstcw.supabase.co/storage/v1/object/public/idea-screenshots/556470e8-ff5c-490a-b949-000d6ca0a6d0/final.png', '2026-02-24T00:00:00Z', '2026-03-13T00:00:00Z');
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('45dd14fb-5b2d-4251-9883-da3552212d7f', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Monica Elliott', 'Analysis Paralysis Helper', 'When there''s so much on your plate that you can''t start - start here.', 'If the struggle to start on any of your massive list of priorities stems from the visceral, overwhelming feeling that you might be picking the wrong thing, this app/site will help bring you back to reality. Using prioritized lists and time estimates, it will help you decide what to do first.', 'completed', 'https://sidequest-tracker.lovable.app/', 'https://yjhgzukmrzufhevzstcw.supabase.co/storage/v1/object/public/idea-screenshots/45dd14fb-5b2d-4251-9883-da3552212d7f/final.png', '2026-02-24T00:00:00Z', '2026-03-13T00:00:00Z');
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('bcddb6cd-d2c6-4c6c-915e-9a7a8369ce24', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Aaron Abolofia', 'Even Grounds', 'Track the bean. Refine the brew. Share the recipe.', 'The perfect cup of coffee isn''t an accident. Even Grounds is the digital companion for the coffee obsessed. Track every bean, every brew, and every note, then follow your favorite roasters, and swap brewing secrets with a community that cares as much about your morning ritual as you do. Stop guessing. Start sharing.', 'completed', 'https://evengrounds.lovable.app/', 'https://yjhgzukmrzufhevzstcw.supabase.co/storage/v1/object/public/idea-screenshots/bcddb6cd-d2c6-4c6c-915e-9a7a8369ce24/final.png', '2026-02-24T00:00:00Z', '2026-03-13T00:00:00Z');
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('4d66f7a5-bd70-4f92-aeec-a22bcaa02533', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Jeremy Meltingtallow', 'Fonda Chez-soi', 'Turn your favorite restaurant dish into a stay-in family cooking night—just paste the URL and let AI recreate the magic at home.', 'This project is for anyone who has a favorite dish at a restaurant but wants to stay home and cook it with their family. You paste the restaurant’s URL, and the system studies the official site, reviews, and photos to understand how the food is made. It builds a restaurant profile that captures flavor style, techniques, and cooking patterns so it can recreate that special dish as faithfully as possible.', 'idea_stage', NULL, 'https://yjhgzukmrzufhevzstcw.supabase.co/storage/v1/object/public/idea-screenshots/4d66f7a5-bd70-4f92-aeec-a22bcaa02533/final.png', '2026-02-24T00:00:00Z', '2026-03-13T00:00:00Z');
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('4a138952-8da8-4670-959f-35b094d1a007', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Mike Miller', 'Obsrving Golf', 'A golf scoring app with friends.', 'Obsrving Golf is a sleek, mobile-first app for tracking your golf scores, calculating your Handicap Index, and competing with friends — letting you log rounds, view stats, and see how you stack up on a shared leaderboard.', 'completed', 'https://ovbsrvinggolf.lovable.app', 'https://yjhgzukmrzufhevzstcw.supabase.co/storage/v1/object/public/idea-screenshots/4a138952-8da8-4670-959f-35b094d1a007/final.png', '2026-02-24T00:00:00Z', '2026-03-13T00:00:00Z');
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('cd51161b-6b18-4401-9a65-70da71a651c9', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Briana Estrellado', 'Travel Buddy', 'Planning a trip should be exciting, not stressful. Budget, manage, and share your perfect getaway with one tool.', 'TravelBuddy is truly your travel buddy. If you have ever tried to plan a trip with multiple locations, events, people, types of transportations, etc. and were just having trouble keeping track of every reservation and who was doing what, you no longer have to manage it all in your head, or on a Google Sheet. Keep track of all your reservations, confirmation codes, budget, and more, get a snapshot with the Itinerary calendar view, and share it with your fellow travelers.', 'in_progress', 'https://ur-travel-buddy.lovable.app/', 'https://yjhgzukmrzufhevzstcw.supabase.co/storage/v1/object/public/idea-screenshots/cd51161b-6b18-4401-9a65-70da71a651c9/final.png', '2026-02-24T00:00:00Z', '2026-03-13T00:00:00Z');
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('24d57972-d128-4b5b-854f-82bcadba6792', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Adam Simons', 'Dreadlist', 'Having a frightful time deciding what to watch for your next horror movie night? Get spooky movie recommendations that are streaming to you.', 'Dreadlist stalks (aggregates) all the horror movies that are currently available on streaming platforms, then lets users filter them so that they can slash the time it takes to find what to watch. A longer term goal would be to showcase the latest horror movie news so that new horror films don''t sneak up behind you.', 'completed', 'https://dreadlist.lovable.app', 'https://yjhgzukmrzufhevzstcw.supabase.co/storage/v1/object/public/idea-screenshots/24d57972-d128-4b5b-854f-82bcadba6792/final.png', '2026-02-24T00:00:00Z', '2026-03-13T00:00:00Z');
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('64efc819-e624-4515-9b84-c1acb380b25f', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Christina Williams', 'ProjectPulse', 'This is a time tracking reminder that will simplify how teams are entering their time. Cutting out the email notification noise.', 'The team will receive a daily personalized Slack message in a project channel every morning. This will include a curated list of projects they worked on the previous day -- complete with direct links for quick time entry. 
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('259759ab-35bf-4c72-9250-8ac0f817bfda', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Sena Hughes Lauer', 'Spill', 'Download your brain into an organized to-do list command center.', 'No more sitting down to write to-do lists, repeat conversations with your partner or kids, or forgetting to add something to the family calendar. With this tool, you''ll simply voice record your unfiltered tasks while you''re driving or making breakfast and have categorized to-do lists, assignments, and an updated calendar waiting for you on the other end. It''s truly the second brain you''ve always wished you had.', 'completed', 'https://spill-it.lovable.app/', 'https://yjhgzukmrzufhevzstcw.supabase.co/storage/v1/object/public/idea-screenshots/259759ab-35bf-4c72-9250-8ac0f817bfda/final.png', '2026-02-24T00:00:00Z', '2026-03-13T00:00:00Z');
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('36dede9f-7f0d-4368-891e-29c3ce4921f9', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Keely Honeywell', 'Horizon', 'Get future and current weather conditions to do your best gardening', NULL, 'completed', 'https://gardener-horizon.lovable.app/', 'https://yjhgzukmrzufhevzstcw.supabase.co/storage/v1/object/public/idea-screenshots/36dede9f-7f0d-4368-891e-29c3ce4921f9/final.png', '2026-02-24T00:00:00Z', '2026-03-13T00:00:00Z');
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('3942de8c-a95c-421c-860f-2e5d2c1ff189', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Joe Haeger', 'The 2026 MLB Batting Leaders', 'Track the biggest batting stats for the 2026 season at a glance.', 'This is for people who don''t want to dig into a gazillion different stats and just want to see those bigger MLB batting stats quickly. You''ll also be able to see which players are tracking up or down on the leaderboards, follow your favorite players, or even guess who will end up at the top of the board by the end of the season.', 'completed', 'https://batstathub.lovable.app/', 'https://yjhgzukmrzufhevzstcw.supabase.co/storage/v1/object/public/idea-screenshots/3942de8c-a95c-421c-860f-2e5d2c1ff189/final.png', '2026-02-24T00:00:00Z', '2026-03-13T00:00:00Z');
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('08ab882e-28ee-48f3-baa4-6291eae13d5e', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Kristin Eiser', 'HomeBase - SOS', 'It takes a village so let us help you find yours. Being a military spouse can be amazing but also lonely. Let us help you navigate it', NULL, 'idea_stage', NULL, NULL, '2026-02-24T00:00:00Z', '2026-03-13T00:00:00Z');
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('4015c04b-cc15-4c87-9812-89bc3e6e85fb', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Chris Hunter', 'Retro-Spective', 'Do you like Retro emulation handheld devices? This app will aggregate all news, reviews, videos, specs, etc. into one central location', 'The retro emulation hobby can be incredibly overwhelming with all the different device types, sources to follow for news and reviews, configuration guides, etc. This app aims to create a central hub that collects data for all the handhelds of the major manufacturers of these devices with an option to compare the specs side-by-side of any of the devices. It will also aggregate news, reviews, and guides from all the most popular sites and youtube', 'completed', 'https://retro-spec.lovable.app/', 'https://yjhgzukmrzufhevzstcw.supabase.co/storage/v1/object/public/idea-screenshots/4015c04b-cc15-4c87-9812-89bc3e6e85fb/final.png', '2026-02-24T00:00:00Z', '2026-03-13T00:00:00Z');
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('42dbf208-3f1f-4926-98fb-beac323931ce', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Callen Fulbright', 'Drift', 'Drift: The AI sleep app that turns your child’s day into a personalized bedtime story. Co-create magic, lower the mental load, and drift off', '🌙 Introducing: Drift
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('577d4629-5fe5-4d63-a620-7283e1528243', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Alliyah Evans', 'Fetch-a-Drink', 'Pick a pup photo based on your mood, and get a cocktail recommendation and recipe card!', 'A fun, personalized way to find a cocktail to make based on how you''re feeling - you could also make it a mocktail!
INSERT INTO ideas (id, event_id, user_id, builder_name, title, pitch, description, status, live_url, final_screenshot_url, created_at, updated_at) VALUES ('aa9041df-b057-4db5-9e56-a0628cf94a18', 'ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'Kelsea Rothaus', 'Frame Fuel', 'Accelerate your storyboard frame documentation. Refine all your notes with this automation tool.', 'Frame Fuel creates formatted automatic animation duration, and polished animation notes where a/b/c+ frames are supported. All you have to do is enter the script, set the number of images, then record your natural spoken description of what''s happening. Stream of consciousness styled writing is also supported.', 'in_progress', NULL, 'https://yjhgzukmrzufhevzstcw.supabase.co/storage/v1/object/public/idea-screenshots/aa9041df-b057-4db5-9e56-a0628cf94a18/final.png', '2026-02-24T00:00:00Z', '2026-03-13T00:00:00Z');
