INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'c21de278-9bdb-5f6d-8297-e3f91d812ebd', 'Really surprised me to see how actually doable it is to go from idea to MVP.', 'Adam Simons', true, '2026-03-30T22:39:24Z', '2026-03-30T22:39:24Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'faaaf2e3-bd21-5d7f-9798-d3802f70036c', 'Don''t worry about making anything perfect, just focus on the minimum viable product.', 'Adam Simons', false, '2026-03-30T22:39:24Z', '2026-03-30T22:39:24Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '44f95f98-fa60-5050-94da-a70004239510', 'I loved seeing my coworkers'' presentations that were based on products that were less work or productivity related. I would encourage someone who''s just starting out to feel free to come up with ideas that are playful and personally relevant. It makes the whole project a lot of fun.', 'Adam Simons', false, '2026-03-30T22:39:24Z', '2026-03-30T22:39:24Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'be69f725-e922-5244-8b63-ed54a9082b2d', 'Hacks-a-thon definitely proved that anyone can make an app or website using current AI and vibe coding platforms.', 'Adam Simons', false, '2026-03-30T22:39:24Z', '2026-03-30T22:39:24Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'e3582627-4c13-5d6e-95fc-fd4333e3a8c6', 'N/A', 'Adam Simons', false, '2026-03-30T22:39:24Z', '2026-03-30T22:39:24Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '2e35b412-db71-5ef3-83f9-cf408fff7901', 'N/A', 'Adam Simons', false, '2026-03-30T22:39:24Z', '2026-03-30T22:39:24Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'bcb8127b-7194-5435-82c5-8f740013cc8d', 'Before my very first prompt, I wish I''d known that giving Lovable reference websites is a really good method to getting closer to a look and style that you''re going for.', 'Adam Simons', false, '2026-03-30T22:39:24Z', '2026-03-30T22:39:24Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'bcb8127b-7194-5435-82c5-8f740013cc8d', 'That the more specific and intentional I was (like tone for example), the better the output! It''s less about asking once and more about collaborating with AI and refining as you go :)', 'Alliyah Evans', true, '2026-03-24T16:35:04Z', '2026-03-24T16:35:04Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'faaaf2e3-bd21-5d7f-9798-d3802f70036c', 'Treat it like a conversation, not a one-shot task; you can keep building on top of what AI gives you!', 'Alliyah Evans', false, '2026-03-24T16:35:04Z', '2026-03-24T16:35:04Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '44f95f98-fa60-5050-94da-a70004239510', 'It just starts with a small idea! Don''t overthink it, just think of AI as your new partner in crime to help you execute it. :)', 'Alliyah Evans', false, '2026-03-24T16:35:04Z', '2026-03-24T16:35:04Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'be69f725-e922-5244-8b63-ed54a9082b2d', 'Definitely! I realized that AI isn''t just for speeding things up - it actually expands what I can create/works WITH me.', 'Alliyah Evans', false, '2026-03-24T16:35:04Z', '2026-03-24T16:35:04Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'e3582627-4c13-5d6e-95fc-fd4333e3a8c6', 'Yes! It gave me the idea to create a content vibe planner - where you plug in your brand, audience, and goals, and it generates a week or month of content ideas that actually feel cohesive (not random trends). Could even be great for S2 socials/help us be more consistent!', 'Alliyah Evans', false, '2026-03-24T16:35:04Z', '2026-03-24T16:35:04Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '2e35b412-db71-5ef3-83f9-cf408fff7901', 'Normally my creative process starts with mapping everything out upfront - however during this, it felt less like designing and more like directing - which actually made me move faster and trust my instincts more! Multiple times along the way I thought oh wait adding this feature could make it even better!', 'Alliyah Evans', false, '2026-03-24T16:35:04Z', '2026-03-24T16:35:04Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'c21de278-9bdb-5f6d-8297-e3f91d812ebd', 'That I hardly had to do anything manually! I was expecting to tweak more myself with design aspects/other elements, but it was so seamless and responsive!', 'Alliyah Evans', false, '2026-03-24T16:35:04Z', '2026-03-24T16:35:04Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '2e35b412-db71-5ef3-83f9-cf408fff7901', 'I can''t make a decision to save my life :)', 'Callen Fulbright', false, '2026-03-31T22:46:09Z', '2026-03-31T22:46:09Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'faaaf2e3-bd21-5d7f-9798-d3802f70036c', 'I think jotting down your plan and running it through chat or gemini and helping them fully flesh out your idea will always help kickstart your project, so I''d suggest that!', 'Callen Fulbright', false, '2026-03-31T22:46:09Z', '2026-03-31T22:46:09Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '44f95f98-fa60-5050-94da-a70004239510', 'Just start! And refine.', 'Callen Fulbright', true, '2026-03-31T22:46:09Z', '2026-03-31T22:46:09Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'be69f725-e922-5244-8b63-ed54a9082b2d', 'I think it makes it feel more approachable, at least the development side of it. I use it for the project management aspects of my job daily but the design/development tasks are actually just as easy.', 'Callen Fulbright', false, '2026-03-31T22:46:09Z', '2026-03-31T22:46:09Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'e3582627-4c13-5d6e-95fc-fd4333e3a8c6', 'I have a ton more ideas I want to try!', 'Callen Fulbright', false, '2026-03-31T22:46:09Z', '2026-03-31T22:46:09Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'bcb8127b-7194-5435-82c5-8f740013cc8d', 'I would have preferred to have a more detailed roadmap from the start, though I recognize that certain things only revealed themselves once I was in the thick of it. Many of the elements I missed were things I likely wouldn''t have known to plan for until I actually reached those stages of the project.', 'Callen Fulbright', false, '2026-03-31T22:46:09Z', '2026-03-31T22:46:09Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'c21de278-9bdb-5f6d-8297-e3f91d812ebd', 'How easy it is! But also how terrible the design features are ;)', 'Callen Fulbright', false, '2026-03-31T22:46:09Z', '2026-03-31T22:46:09Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'c21de278-9bdb-5f6d-8297-e3f91d812ebd', 'How easy it was to go from having an idea to something tangible and (for the most part) working.', 'Chris Hunter', false, '2026-03-24T17:07:12Z', '2026-03-24T17:07:12Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'faaaf2e3-bd21-5d7f-9798-d3802f70036c', 'I think approaching it with an open mind would be the biggest mindset shift that could help someone who has any of the same reservations that I did', 'Chris Hunter', false, '2026-03-24T17:07:12Z', '2026-03-24T17:07:12Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '44f95f98-fa60-5050-94da-a70004239510', 'Just jump in. It''s not even close to as daunting as it seems like it''s going to be.', 'Chris Hunter', true, '2026-03-24T17:07:12Z', '2026-03-24T17:07:12Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'be69f725-e922-5244-8b63-ed54a9082b2d', 'Yes it did. It opened my eyes a bit to the possibilities. Admittedly, I have a bit of biases against GenAI when it comes to a creative final output but it showed me that GenAI can be good for productivity and problem solving. I think I needed something like this to get more on board.', 'Chris Hunter', false, '2026-03-24T17:07:12Z', '2026-03-24T17:07:12Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'e3582627-4c13-5d6e-95fc-fd4333e3a8c6', 'Not YET but I think it''ll definitely open up a new avenue for problem solving.', 'Chris Hunter', false, '2026-03-24T17:07:12Z', '2026-03-24T17:07:12Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '2e35b412-db71-5ef3-83f9-cf408fff7901', 'That my visual process doesn''t always translate to a text-based one', 'Chris Hunter', false, '2026-03-24T17:07:12Z', '2026-03-24T17:07:12Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'bcb8127b-7194-5435-82c5-8f740013cc8d', 'That it wasn''t going to be that hard', 'Chris Hunter', false, '2026-03-24T17:07:12Z', '2026-03-24T17:07:12Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'faaaf2e3-bd21-5d7f-9798-d3802f70036c', 'I''d love to hear what the creative team suggests, especially since clients have been challenged to do more with less budget and they continue to encourage the use of AI to build in efficiencies.', 'Christina Williams', false, '2026-03-24T18:09:40Z', '2026-03-24T18:09:40Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'c21de278-9bdb-5f6d-8297-e3f91d812ebd', 'Honestly, it really surprised me how easy the process was. And, how Lovable offered additional features and functionality to build a more robust experience.', 'Christina Williams', false, '2026-03-24T18:09:40Z', '2026-03-24T18:09:40Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'bcb8127b-7194-5435-82c5-8f740013cc8d', 'The main learning is how literal Lovable was with my feedback and requests, so I learned to be more holistic and detailed with my requests.', 'Christina Williams', false, '2026-03-24T18:09:40Z', '2026-03-24T18:09:40Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '2e35b412-db71-5ef3-83f9-cf408fff7901', 'I definitely relied on existing sites and tools to convey how I wanted the dashboard visually structured. But, I knew what flow I wanted it to reflect.', 'Christina Williams', false, '2026-03-24T18:09:40Z', '2026-03-24T18:09:40Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'e3582627-4c13-5d6e-95fc-fd4333e3a8c6', 'I have some ideas around RV travel, but will need to really deep dive what already exists in the market.', 'Christina Williams', false, '2026-03-24T18:09:40Z', '2026-03-24T18:09:40Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'be69f725-e922-5244-8b63-ed54a9082b2d', 'Definitely! If you have a vision, you can build it. This is such an easy process. The main challenge is staying focused on your original idea, because AI offers so many incredible ideas that it''s easy to keep adding to it.', 'Christina Williams', false, '2026-03-24T18:09:40Z', '2026-03-24T18:09:40Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '44f95f98-fa60-5050-94da-a70004239510', 'Just get started. AI will guide you and offer recommendations that may not have crossed your mind.', 'Christina Williams', false, '2026-03-24T18:09:40Z', '2026-03-24T18:09:40Z');
