INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'faaaf2e3-bd21-5d7f-9798-d3802f70036c', 'I''ll speak for devs. I''d say look into awesome resources. After building my project I searched for awesome opencode and found https://github.com/awesome-opencode/awesome-opencode. It has many resources that supercharge vibe coding.', 'Jeremy Meltingtallow', false, '2026-04-01T00:19:09Z', '2026-04-01T00:19:09Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'c21de278-9bdb-5f6d-8297-e3f91d812ebd', 'I was surprised by how accessible vibe coding can be and how quickly it can build projects.', 'Jeremy Meltingtallow', false, '2026-04-01T00:19:09Z', '2026-04-01T00:19:09Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'bcb8127b-7194-5435-82c5-8f740013cc8d', 'The architecture I wanted to build upon and component library I wanted to use. I think if I knew both of those then I may have been more successful in making small changes.', 'Jeremy Meltingtallow', false, '2026-04-01T00:19:09Z', '2026-04-01T00:19:09Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '2e35b412-db71-5ef3-83f9-cf408fff7901', 'I found that I was able to ideate quickly and build out stronger prompts from reading the reasoning and code it created.', 'Jeremy Meltingtallow', false, '2026-04-01T00:19:09Z', '2026-04-01T00:19:09Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'e3582627-4c13-5d6e-95fc-fd4333e3a8c6', 'I''d be interested in building a google maps meets recipes. It could save some headache when your loved one isn''t answering their phone.', 'Jeremy Meltingtallow', false, '2026-04-01T00:19:09Z', '2026-04-01T00:19:09Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'be69f725-e922-5244-8b63-ed54a9082b2d', 'It did change how I think about AI. I wasn''t aware at how capable it was at building projects. I noticed its very good at building from scratch and can have issues when making updates. It took me down a rabbit trail of greenfield vs brownfield. It''s been fun building a workflow that allows team vibing.', 'Jeremy Meltingtallow', false, '2026-04-01T00:19:09Z', '2026-04-01T00:19:09Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '44f95f98-fa60-5050-94da-a70004239510', 'I''d say just go for it. It is much simpler than you may realize.', 'Jeremy Meltingtallow', false, '2026-04-01T00:19:09Z', '2026-04-01T00:19:09Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'c21de278-9bdb-5f6d-8297-e3f91d812ebd', 'It was surprising to see how intuitive the AI was when it came to the functionality I was looking for. I''d type something in that I believed I had thought through, and Lovable would spit something out so much more complex and necessary to the overall project. I also loved that it did security checks and would fix things that I would never be able to see or think of.', 'Joe Haeger', false, '2026-03-24T16:20:44Z', '2026-03-24T16:20:44Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'faaaf2e3-bd21-5d7f-9798-d3802f70036c', 'It sounds a little silly and simple, but shifting the mindset to Just say yes is all it might take for some people. It''s all trial and error, so getting in there and giving it a shot is the best way to garner some excitement for this approach.', 'Joe Haeger', true, '2026-03-24T16:20:44Z', '2026-03-24T16:20:44Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '44f95f98-fa60-5050-94da-a70004239510', 'Just go for it. Even if you have a half-baked idea, AI/Lovable can help you figure out the direction you want to go. For example, I didn''t really know what I wanted the interface to look like, but after Lovable spit something out, I knew what I didn''t want it to look like. After some back and forth, I got it to a spot I was happy with.', 'Joe Haeger', false, '2026-03-24T16:20:44Z', '2026-03-24T16:20:44Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'be69f725-e922-5244-8b63-ed54a9082b2d', 'This showed me what AI is capable of. I used ChatGPT for the logo and Lovable came up with the copy for the site. It''s all pretty standard, but usable. It''s wild to see how quickly it''s able to spin this stuff up.', 'Joe Haeger', false, '2026-03-24T16:20:44Z', '2026-03-24T16:20:44Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'e3582627-4c13-5d6e-95fc-fd4333e3a8c6', 'I like tracking progress, so I was thinking about creating a site where you can log your creative time/output. For writing, we generally do that by word count. So the site would have inputs for writing time and word count.', 'Joe Haeger', false, '2026-03-24T16:20:44Z', '2026-03-24T16:20:44Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '2e35b412-db71-5ef3-83f9-cf408fff7901', 'It''s one of those reminders that even with a lot of planning, you can still be MORE prepared. Take a beat to think things through one more time because you''ll inevitably think of even more cool stuff that can get added into your creative venture. Also, don''t shy away from collaboration.', 'Joe Haeger', false, '2026-03-24T16:20:44Z', '2026-03-24T16:20:44Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'bcb8127b-7194-5435-82c5-8f740013cc8d', 'I think my project came together pretty seamlessly. I wanted to keep it simple and even the added features I put in were piecemeal, so it didn''t feel like anything clogged up the process of the build. Taking things one step at a time worked well. Basically, that first prompt needs to be the core foundation for the site and then you can add the flourishes/fun stuff on top.', 'Joe Haeger', false, '2026-03-24T16:20:44Z', '2026-03-24T16:20:44Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'bcb8127b-7194-5435-82c5-8f740013cc8d', 'The limitations of Lovable, Adobe InDesign, and Google Gems. None of those platforms can communicate with each other directly.', 'Kelsea Rothaus', false, '2026-03-31T22:18:48Z', '2026-03-31T22:18:48Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'faaaf2e3-bd21-5d7f-9798-d3802f70036c', 'Getting started is the hardest part. Having a super clear process documentation and continuing to only point to that would help improve focus. For instance, Zero Prompter was so cool! How do we tell Lovable how to use that to get started building my project?', 'Kelsea Rothaus', false, '2026-03-31T22:18:48Z', '2026-03-31T22:18:48Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '44f95f98-fa60-5050-94da-a70004239510', 'Take your original idea and make it way more simple – have a clear vision of your end goal. Your project will grow naturally anyways.', 'Kelsea Rothaus', false, '2026-03-31T22:18:48Z', '2026-03-31T22:18:48Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'e3582627-4c13-5d6e-95fc-fd4333e3a8c6', 'I think this Frame Fuel tool could be really useful for our team. Even without the seamless integration. I would like to continue finessing it and see what the easiest method of adoption might be for our team.', 'Kelsea Rothaus', false, '2026-03-31T22:18:48Z', '2026-03-31T22:18:48Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '2e35b412-db71-5ef3-83f9-cf408fff7901', 'I learned that I''m more opinionated about efficiency and workflows than I thought. Hitting road blocks became quite frustrating at times. But, I was surprised at how easy it was to communicate the needs of my tool and then identify what was/wasn''t possible.', 'Kelsea Rothaus', false, '2026-03-31T22:18:48Z', '2026-03-31T22:18:48Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'be69f725-e922-5244-8b63-ed54a9082b2d', 'Yes, I''m more open to the idea of vibe coding for non-secure work.', 'Kelsea Rothaus', false, '2026-03-31T22:18:48Z', '2026-03-31T22:18:48Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'c21de278-9bdb-5f6d-8297-e3f91d812ebd', 'A simple idea turned into a complex design. There were many details I wouldn''t have thought of until I started designing within the working prototype. Having that was pivotal.', 'Kelsea Rothaus', false, '2026-03-31T22:18:48Z', '2026-03-31T22:18:48Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'faaaf2e3-bd21-5d7f-9798-d3802f70036c', 'To focus initially on making something for yourself and not for other people. I really like that this was the goal with this project, and noticed that it really helps you focus on a quality product.', 'Monica Elliott', false, '2026-03-26T18:42:23Z', '2026-03-26T18:42:23Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'bcb8127b-7194-5435-82c5-8f740013cc8d', 'How glitchy it can be when your ui gets complicated. It did really weird things like moving the background in front of the text, change the logic when making an edit as simple as a text color, etc.', 'Monica Elliott', false, '2026-03-26T18:42:23Z', '2026-03-26T18:42:23Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '2e35b412-db71-5ef3-83f9-cf408fff7901', 'I discovered that often-times a function would sound good in my head, but in action it wasn''t quite right and needed me to go back to the drawing board.', 'Monica Elliott', false, '2026-03-26T18:42:23Z', '2026-03-26T18:42:23Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'e3582627-4c13-5d6e-95fc-fd4333e3a8c6', 'Probably! I have some half-baked ideas I would love to explore in the future.', 'Monica Elliott', false, '2026-03-26T18:42:23Z', '2026-03-26T18:42:23Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'be69f725-e922-5244-8b63-ed54a9082b2d', 'Duuuude...I''m still not sure. I have crazy mixed feelings about ai. On one hand, I am perpetually excited to dive head-on into new technology. On the other hand, the ethical and environmental implications still linger in the back of my head.', 'Monica Elliott', false, '2026-03-26T18:42:23Z', '2026-03-26T18:42:23Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '44f95f98-fa60-5050-94da-a70004239510', 'Just go for it! The ai-promptr was very helpful at breaking the seal for getting started. And don''t think too hard about it.', 'Monica Elliott', false, '2026-03-26T18:42:23Z', '2026-03-26T18:42:23Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'c21de278-9bdb-5f6d-8297-e3f91d812ebd', 'How much it would open me up to trying more ai', 'Monica Elliott', false, '2026-03-26T18:42:23Z', '2026-03-26T18:42:23Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'faaaf2e3-bd21-5d7f-9798-d3802f70036c', 'Specifically, it''s the realization that you don''t have to choose between being a designer or a developer—you can be a product architect.', 'Joe Moore', true, '2026-03-24T16:27:45Z', '2026-03-24T16:27:45Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'c21de278-9bdb-5f6d-8297-e3f91d812ebd', 'I''m used to AI tools that just handle the plumbing, so seeing the design-forward output from Lovable and Google AI Studio was a revelation.', 'Joe Moore', false, '2026-03-24T16:27:45Z', '2026-03-24T16:27:45Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'bcb8127b-7194-5435-82c5-8f740013cc8d', 'My biggest takeaway: Don''t underestimate the UI. I went in focusing on low-level logic, but the real power of tools like Google AI Studio and Lovable is their ability to bridge the gap between a rough idea and a polished, launch-ready aesthetic instantly.', 'Joe Moore', false, '2026-03-24T16:27:45Z', '2026-03-24T16:27:45Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '2e35b412-db71-5ef3-83f9-cf408fff7901', 'My process shifted from function-first to experience-first. I found that I could lean into complex animations and bold design choices early on, trusting the AI to maintain the technical logic while I focused on the actual feel of the product.', 'Joe Moore', false, '2026-03-24T16:27:45Z', '2026-03-24T16:27:45Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'e3582627-4c13-5d6e-95fc-fd4333e3a8c6', 'Yes, I am interested in the workflow of design first with Google AI Studio as a template then pull the code down to work on the project in a more powerful AI model using dev tools like cursor', 'Joe Moore', false, '2026-03-24T16:27:45Z', '2026-03-24T16:27:45Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'be69f725-e922-5244-8b63-ed54a9082b2d', 'Absolutely. It''s completely shifted my pipeline. I''m now moving toward a Design-First workflow: using Google AI Studio to rapidly prototype the UI and UX templates, then pulling that high-fidelity code into Cursor.', 'Joe Moore', false, '2026-03-24T16:27:45Z', '2026-03-24T16:27:45Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '44f95f98-fa60-5050-94da-a70004239510', 'My advice? Treat your first few sessions like a digital sandbox. Go with the flow and see where the model takes your ideas. To quote Bob Ross, We don''t make mistakes, just happy accidents.', 'Joe Moore', false, '2026-03-24T16:27:45Z', '2026-03-24T16:27:45Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'bcb8127b-7194-5435-82c5-8f740013cc8d', 'About the planned feature, so the agent doesn''t just start building right away', 'Nick Murto', false, '2026-03-24T02:51:22Z', '2026-03-24T02:51:22Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'faaaf2e3-bd21-5d7f-9798-d3802f70036c', 'Maybe a video how-to could help.', 'Nick Murto', false, '2026-03-24T02:51:22Z', '2026-03-24T02:51:22Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '44f95f98-fa60-5050-94da-a70004239510', 'Don''t be afraid to jump in and know that you might throw away the first amount of work you did, but you learned something along the way.', 'Nick Murto', false, '2026-03-24T02:51:22Z', '2026-03-24T02:51:22Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'be69f725-e922-5244-8b63-ed54a9082b2d', 'Completely.', 'Nick Murto', false, '2026-03-24T02:51:22Z', '2026-03-24T02:51:22Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'e3582627-4c13-5d6e-95fc-fd4333e3a8c6', '100% yes and then some.', 'Nick Murto', false, '2026-03-24T02:51:22Z', '2026-03-24T02:51:22Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '2e35b412-db71-5ef3-83f9-cf408fff7901', 'That the things I want are all doable.', 'Nick Murto', false, '2026-03-24T02:51:22Z', '2026-03-24T02:51:22Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'c21de278-9bdb-5f6d-8297-e3f91d812ebd', 'How much fun everybody else had', 'Nick Murto', true, '2026-03-24T02:51:22Z', '2026-03-24T02:51:22Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'faaaf2e3-bd21-5d7f-9798-d3802f70036c', 'Don''t overthink it. Also, I didn''t get a chance to use it/haven''t yet, but it seems like Google Studio was a super strong tool to use for design and overall planning.', 'Sena Hughes Lauer', false, '2026-03-31T16:45:31Z', '2026-03-31T16:45:31Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'bcb8127b-7194-5435-82c5-8f740013cc8d', 'I didn''t totally understand that when you submitted something to Lovable it would build it live, so I would have spent a bit more time planning elsewhere or using the planning feature but it all worked out.', 'Sena Hughes Lauer', false, '2026-03-31T16:45:31Z', '2026-03-31T16:45:31Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '2e35b412-db71-5ef3-83f9-cf408fff7901', '1. I have good instincts for UI and had decent success creating what I wanted, just need more time to perfect it. 2. Giving design direction to AI is hard.', 'Sena Hughes Lauer', false, '2026-03-31T16:45:31Z', '2026-03-31T16:45:31Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'e3582627-4c13-5d6e-95fc-fd4333e3a8c6', 'Potentially! I definitely can see the benefit of the tool I made and am continuing to use/test it, and this also unlocked more ideas for how to use vibe coding.', 'Sena Hughes Lauer', false, '2026-03-31T16:45:31Z', '2026-03-31T16:45:31Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'be69f725-e922-5244-8b63-ed54a9082b2d', 'Yes! Per above, it was easier than I expected and super cool to think that it''s possible! I have definitely found myself thinking in response to every problem I have recently, oh I could make a solution for that rather than someone should make an app for that.', 'Sena Hughes Lauer', true, '2026-03-31T16:45:31Z', '2026-03-31T16:45:31Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, '44f95f98-fa60-5050-94da-a70004239510', 'Just let it be fun and play around with it. Honestly, it''s probably easier for me as a non-creative than someone who is more perfectionistic about design and dev. But that said, let it be easy, don''t build your first project thinking it''s a gold mine. Just get the hang of it.', 'Sena Hughes Lauer', false, '2026-03-31T16:45:31Z', '2026-03-31T16:45:31Z');
INSERT INTO reflections (event_id, user_id, question_id, answer, respondent_name, is_featured, created_at, updated_at) VALUES ('ae0b0e99-8756-50f2-8960-c372c9817704', NULL, 'c21de278-9bdb-5f6d-8297-e3f91d812ebd', 'Honestly, how easy/fun it was! Which I know was the point :)', 'Sena Hughes Lauer', false, '2026-03-31T16:45:31Z', '2026-03-31T16:45:31Z');
